package com.zoro.zoromart.service;
import com.zoro.zoromart.dao.ProductDAO;import org.junit.jupiter.api.*;import java.sql.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;
/** DAO integration tests against an isolated in-memory H2 schema. */
class ProductDAOTest {private Connection connection;private ProductDAO dao;@BeforeEach void setUp()throws Exception{connection=DriverManager.getConnection("jdbc:h2:mem:producttest;DB_CLOSE_DELAY=-1","sa","");try(Statement s=connection.createStatement()){s.execute("DROP ALL OBJECTS");s.execute("CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100),email VARCHAR(190),password_hash VARCHAR(100),role VARCHAR(10),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");s.execute("INSERT INTO users(name,email,password_hash,role) VALUES('Seller','seller@test.local','x','SELLER')");s.execute("CREATE TABLE products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,seller_id BIGINT,name VARCHAR(160),description VARCHAR(2000),price DECIMAL(10,2),stock_qty INT,category VARCHAR(80),image_url VARCHAR(1000),active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");}dao=new ProductDAO(connection);}@AfterEach void tearDown()throws Exception{connection.close();}@Test void createsAndSearchesProduct()throws Exception{long id=dao.create(1,"Headphones","Wireless headphones",new BigDecimal("19.99"),4,"Electronics",null);assertNotNull(dao.get(id));assertEquals(1,dao.search("headphones","Electronics").size());}@Test void searchInputIsTreatedAsData()throws Exception{dao.create(1,"Lamp","Desk lamp",new BigDecimal("12.00"),2,"Home",null);assertTrue(dao.search("' OR 1=1 --","Home").isEmpty());}}
